import sys
import json
import numpy as np
import pandas as pd

def to_float(x, decimals=2):
    return round(float(x), decimals)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # Totals (skip NaNs automatically with sum, but need to check for all-NaN columns)
    rev_tw_total = df['Revenue_TW'].sum(skipna=True)
    rev_lw_total = df['Revenue_LW'].sum(skipna=True)
    rev_ly_series = df['Revenue_LY'].dropna()
    rev_ly_total = rev_ly_series.sum() if len(rev_ly_series) > 0 else None

    units_tw_total = df['Units_TW'].sum(skipna=True)
    units_lw_total = df['Units_LW'].sum(skipna=True)
    orders_tw_total = df['Orders_TW'].sum(skipna=True)
    orders_lw_total = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(rev_tw_total), "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(rev_lw_total), "formula": "sum(Revenue_LW)"
    })
    if rev_ly_total is not None:
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": to_float(rev_ly_total), "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(units_tw_total), "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(units_lw_total), "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(orders_tw_total), "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(orders_lw_total), "formula": "sum(Orders_LW)"
    })

    if rev_lw_total and rev_lw_total != 0:
        wow_total = (rev_tw_total - rev_lw_total) / rev_lw_total * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(wow_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if rev_ly_total is not None and rev_ly_total != 0:
        yoy_total = (rev_tw_total - rev_ly_total) / rev_ly_total * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(yoy_total, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # Sort by Rank for top entities
    df_sorted = df.sort_values('Rank', na_position='last')

    # Top entity by revenue
    if len(df_sorted) > 0:
        top_row = df_sorted.iloc[0]
        facts.append({
            "entity": top_row['Entity'], "metric": "rank", "period": "TW",
            "value": to_float(top_row['Rank'], 0),
            "formula": "Rank by Revenue_TW (1 = highest)"
        })

    # Per-entity facts: revenue TW/LW/LY, share, WoW, YoY for top entities (limit to top N to stay <=25)
    max_entities = 8
    count = 0
    for _, row in df_sorted.iterrows():
        if count >= max_entities:
            break
        entity = row['Entity']

        if pd.notna(row.get('Revenue_TW')):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "TW",
                "value": to_float(row['Revenue_TW']),
                "formula": "Revenue_TW"
            })

        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": entity, "metric": "share", "period": "TW",
                "value": to_float(row['Share_Pct'], 1),
                "formula": "Revenue_TW / sum(Revenue_TW) * 100"
            })

        if pd.notna(row.get('WoW_Pct')):
            facts.append({
                "entity": entity, "metric": "revenue", "period": "WoW",
                "value": to_float(row['WoW_Pct'], 1),
                "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
            })

        count += 1

    # Biggest WoW mover (by absolute pct) among entities with non-null WoW_Pct
    wow_valid = df.dropna(subset=['WoW_Pct'])
    if len(wow_valid) > 0:
        idx = wow_valid['WoW_Pct'].abs().idxmax()
        row = df.loc[idx]
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(row['WoW_Pct'], 1),
            "formula": "Biggest WoW mover: (Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # Biggest YoY mover (by absolute pct) among entities with non-null YoY_Pct
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if len(yoy_valid) > 0:
        idx = yoy_valid['YoY_Pct'].abs().idxmax()
        row = df.loc[idx]
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(row['YoY_Pct'], 1),
            "formula": "Biggest YoY mover: (Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Trim to 25 facts max
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
